using System;
using System.Collections;
using System.Collections.Generic;
using System.Diagnostics;
using System.IO;
using System.Runtime.InteropServices;
using UnityEngine;
using UnityEngine.Profiling;
using UnityEngine.Rendering;
namespace MassiveArmy.Planetary {
    public sealed class SettlementAmbientValidation:MonoBehaviour {
        struct Node {public Vector4 position;public int a,b,c,d;}
        struct Goal {public int node,team,active,pad;}
        struct Order {public uint home,target,team,model;public Vector4 parameters;}
        [Serializable]sealed class Result {public int population,outdoorAgents,frames;public double medianMs,p95Ms,ticksPerSecond;public long buffers,allocated,reserved,workingSet,privateBytes;}
        [Serializable]sealed class Report {public string status="PASS",error="",scope="Equivalent road network and total population; legacy all-resident outdoor walkers versus the requested capped outdoor pool. No army scale is changed. GPU pedestrian dispatch/fence plus seeded daily schedule generation; no full-world rendering, army or fog acceptance claim.";public List<string> checks=new List<string>();public List<Result> results=new List<Result>();}
        [StructLayout(LayoutKind.Sequential)]struct MemoryCounters {public uint size,faults;public UIntPtr peakWorkingSet,workingSet,peakPaged,paged,peakNonPaged,nonPaged,pagefile,peakPagefile,privateBytes;}
        [DllImport("kernel32.dll")]static extern IntPtr GetCurrentProcess();
        [DllImport("psapi.dll")]static extern bool GetProcessMemoryInfo(IntPtr process,out MemoryCounters counters,uint size);
        readonly Report report=new Report();string output;int errors;
        [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.BeforeSceneLoad)]static void Install(){if(Array.IndexOf(Environment.GetCommandLineArgs(),"-ambient-settlement-validation")>=0)new GameObject("Ambient settlement validation").AddComponent<SettlementAmbientValidation>();}
        void Awake(){var args=Environment.GetCommandLineArgs();int at=Array.IndexOf(args,"-planet-output");output=at<0?"TestResults/AmbientSettlement/Run":args[at+1];Directory.CreateDirectory(output);Application.targetFrameRate=-1;QualitySettings.vSyncCount=0;Application.runInBackground=true;Application.logMessageReceived+=OnLog;}
        void OnLog(string message,string trace,LogType type){if(type==LogType.Error||type==LogType.Exception||type==LogType.Assert)errors++;}
        IEnumerator Start(){var run=Run();while(true){bool more;object value=null;try{more=run.MoveNext();if(more)value=run.Current;}catch(Exception e){report.status="FAIL";report.error=e.ToString();break;}if(!more)break;yield return value;}if(errors>0){report.status="FAIL";report.error+=" Runtime errors: "+errors;}File.WriteAllText(Path.Combine(output,"comparison.json"),JsonUtility.ToJson(report,true));Application.Quit(report.status=="PASS"?0:1);}
        void Check(bool value,string message){if(!value)throw new InvalidOperationException(message);report.checks.Add(message);}
        IEnumerator Run(){
            var a=new SettlementDailySchedule(17,21,3);var b=new SettlementDailySchedule(17,21,3);var c=new SettlementDailySchedule(17,21,4);var d=new SettlementDailySchedule(17,22,3);
            Check(a.start==b.start&&a.endLeisure==b.endLeisure,"Same identity, job and day reproduce a schedule");Check(a.start!=c.start&&a.start!=d.start,"Day and job changes change generated appointments");Check(a.start<a.finish&&a.leisure<a.endLeisure&&a.endLeisure<=21,"Generated appointments have valid chronological ranges");Check(JsonUtility.ToJson(new ResidentState()).IndexOf("leisure",StringComparison.Ordinal)<0,"Biographies do not serialize generated schedules");
            var town=new ColonyState{id=19};for(int i=1;i<=200;i++)town.residents.Add(new ResidentState{id=i,age=25});var roster=new SettlementOutdoorRoster();roster.Refresh(town,16,4);var chosen=new List<ResidentState>(roster.People);town.residents.Add(new ResidentState{id=201,age=25});roster.Refresh(town,16,4);Check(roster.People.Count==16&&roster.People.TrueForAll(x=>chosen.Contains(x)),"Births do not reroll the outdoor roster within the same day");chosen[0].alive=false;roster.Refresh(town,16,4);Check(roster.People.Count==16&&!roster.People.Contains(chosen[0]),"A dead member frees its outdoor slot");roster.Refresh(town,4,5);Check(roster.People.Count==4,"The next day obeys a changed outdoor cap");
            var catalogue=CivilisationCatalogue.Load();var colony=new ColonyState();colony.inventory.Bind(catalogue);colony.transportReserve.Bind(catalogue);var item=new SurfaceInstallation();item.inventory.Bind(catalogue);item.inventory.Deposit("food",25);
            CivilisationRuntime.BindSharedInstallation(catalogue,colony,item);Check(item.inventory.stock.Count==0&&colony.transportReserve.Get("food")==25,"Legacy installation stock moves once into the preserved reserve");CivilisationRuntime.BindSharedInstallation(catalogue,colony,item);Check(colony.transportReserve.Get("food")==25,"Repeated shared binding does not duplicate legacy stock");colony.inventory.Deposit("food",20);Check(item.inventory.Get("food")==20,"Installation sees the actual shared balance");Check(item.inventory.Spend("food",3)&&colony.inventory.Get("food")==17,"Installation consumption charges the shared balance once");item.inventory.Deposit("food",4);Check(colony.inventory.Get("food")==21,"Installation output reaches shared stock without a truck");Check(JsonUtility.ToJson(item.inventory).IndexOf("food",StringComparison.Ordinal)<0,"Shared installation views serialize no duplicate stock");
            var persisted=JsonUtility.FromJson<PlanetState>(JsonUtility.ToJson(new PlanetState{landTiles=new List<SettlementLandTile>{new SettlementLandTile{kind=SettlementLandKind.Farm,crop="wheat",field=new SurfaceInstallation{growth=.75},harvestAt=123}}}));Check(persisted.landTiles[0].field.growth==.75&&persisted.landTiles[0].harvestAt==123,"Field growth and harvest progress survive save roundtrip");
            var settings=ScriptableObject.CreateInstance<CivilisationSettings>();var wheat=Array.Find(catalogue.crops,x=>x.id=="wheat");var field=new SurfaceInstallation{crop="wheat"};field.inventory.Bind(catalogue);field.inventory.Deposit("seeds",10);field.inventory.Deposit("water",10000);var planet=new PlanetState{environment=new CelestialEnvironment{atmosphere=true,temperature=wheat.temperature}};
            CivilisationRuntime.AdvanceCrop(catalogue,settings,field,planet,wheat.growthSeconds*2,false);Check(field.growth==1&&field.harvests==0,"A ripe crop waits for its harvest sweep without crediting output");field.inventory.Spend("water",field.inventory.Get("water"));CivilisationRuntime.AdvanceCrop(catalogue,settings,field,planet,0,true);Check(field.harvests==1&&field.growth==0&&field.inventory.Get("grain")>0,"Completed sweep harvests even when the water buffer has run dry");Destroy(settings);
            var render=CheckFields();while(render.MoveNext())yield return render.Current;
            foreach(int agents in new[]{4096,256}){var scenario=Walkers(agents);while(scenario.MoveNext())yield return scenario.Current;}
            var park=Walkers(1,true);while(park.MoveNext())yield return park.Current;
        }
        IEnumerator CheckFields(){
            var shader=Resources.Load<Shader>("MassiveArmy/SettlementFields");Check(shader!=null&&shader.isSupported,"Procedural field shader is available on the graphics device");var material=new Material(shader);var fieldBuffer=new GraphicsBuffer(GraphicsBuffer.Target.Structured,1,96);var texture=new RenderTexture(128,128,24);texture.Create();var cameraObject=new GameObject("Field validation camera");var camera=cameraObject.AddComponent<Camera>();camera.enabled=false;cameraObject.transform.position=new Vector3(0,7,-12);cameraObject.transform.LookAt(new Vector3(0,.4f,0));camera.nearClipPlane=.1f;camera.farClipPlane=100;camera.aspect=1;
            try{var values=new Vector4[]{new Vector4(0,0,0,4),Vector4.zero,new Vector4(1,0,0,0),new Vector4(0,0,1,0),new Vector4(0,1,0,0),new Vector4(.9f,-1,.7f,.65f)};fieldBuffer.SetData(values);material.SetBuffer("_Fields",fieldBuffer);material.SetInt("_Clumps",6);material.SetFloat("_HarvestSeconds",20);material.SetFloat("_Clock",5);material.SetVector("_CentreHigh",Vector3.zero);material.SetVector("_CentreLow",Vector3.zero);material.SetVector("_Camera",cameraObject.transform.position);material.SetVector("_ArmyLightDirection",new Vector3(0,1,-1).normalized);material.SetVector("_ArmyDirectLight",Vector3.one);material.SetFloat("_ArmyAmbientLight",1);material.SetMatrix("_VP",GL.GetGPUProjectionMatrix(camera.projectionMatrix,true)*camera.worldToCameraMatrix);
                int previous=-1;for(int pass=0;pass<2;pass++){if(pass==1){values[5].y=0;fieldBuffer.SetData(values);}using(var commands=new CommandBuffer()){commands.SetRenderTarget(texture);commands.ClearRenderTarget(true,true,Color.black);commands.DrawProcedural(Matrix4x4.identity,material,0,MeshTopology.Triangles,6*6*12+252,1);Graphics.ExecuteCommandBuffer(commands);}var read=AsyncGPUReadback.Request(texture,0,TextureFormat.RGBA32);while(!read.done)yield return null;Check(!read.hasError,"Field/crop draw completes on GPU: "+pass);var pixels=read.GetData<Color32>();int lit=0;foreach(var pixel in pixels)if(pixel.r+pixel.g+pixel.b>20)lit++;Check(lit>20,"Crops/tractor produce visible pixels: "+pass);if(previous>=0)Check(lit!=previous,"Harvest sweep changes the rendered field and displays its tractor");previous=lit;}
            }finally{fieldBuffer.Dispose();texture.Release();Destroy(texture);Destroy(material);Destroy(cameraObject);}
        }
        IEnumerator Walkers(int agents,bool park=false){
            const int roadCount=4096,goalCount=16,frames=10000;var shader=Instantiate(Resources.Load<ComputeShader>("MassiveArmy/SettlementCitizens"));var buffers=new List<GraphicsBuffer>();GraphicsBuffer B(int n,int stride){var b=new GraphicsBuffer(GraphicsBuffer.Target.Structured,n,stride);buffers.Add(b);return b;}
            var nodes=B(roadCount,32);var goals=B(goalCount,16);var orders=B(agents,32);var parents=B(roadCount*goalCount,4);var queue=B(roadCount*goalCount,4);var search=B(goalCount,16);var walkers=B(agents,32);var civic=B(agents,48);var poses=B(agents,80);var visible=B(agents,4);var draw=B(4,4);var patrol=B(PlanetCountries.Maximum*9,4);var areas=B(goalCount,64);
            try{
                var graph=new Node[roadCount];for(int i=0;i<roadCount;i++)graph[i]=new Node{position=new Vector4(i*4,120000,0,0),a=i>0?i-1:-1,b=i+1<roadCount?i+1:-1,c=-1,d=-1};nodes.SetData(graph);var destinations=new Goal[goalCount];for(int i=0;i<goalCount;i++)destinations[i]=new Goal{node=i*256,active=1,pad=park&&i==0?1:0};goals.SetData(destinations);
                var input=new Order[agents];for(int i=0;i<agents;i++)input[i]=new Order{home=park?0u:(uint)(i%roadCount),target=park?0u:(uint)((i/256)%goalCount),parameters=new Vector4(i+1,park?8:0,1,1)};orders.SetData(input);walkers.SetData(new Vector4[agents*2]);civic.SetData(new Vector4[agents*3]);patrol.SetData(new uint[PlanetCountries.Maximum*9]);var area=new Vector4[goalCount*4];area[0]=new Vector4(0,120000,0,4);area[1]=new Vector4(1,park?.1f:0,0,0);area[2]=new Vector4(0,1,0,0);area[3]=new Vector4(0,0,0,park?.2f:0);areas.SetData(area);
                int clear=shader.FindKernel("ClearFlows"),build=shader.FindKernel("BuildFlows"),walk=shader.FindKernel("Walk"),reset=shader.FindKernel("ResetDraw");foreach(int kernel in new[]{clear,build,walk}){shader.SetBuffer(kernel,"_Nodes",nodes);shader.SetBuffer(kernel,"_Goals",goals);shader.SetBuffer(kernel,"_Parents",parents);shader.SetBuffer(kernel,"_Queue",queue);shader.SetBuffer(kernel,"_Search",search);}shader.SetBuffer(walk,"_Orders",orders);shader.SetBuffer(walk,"_Walkers",walkers);shader.SetBuffer(walk,"_CivicStates",civic);shader.SetBuffer(walk,"_CargoPoses",poses);shader.SetBuffer(walk,"_CitizenVisible",visible);shader.SetBuffer(walk,"_DrawArgs",draw);shader.SetBuffer(walk,"_PatrolGoals",patrol);shader.SetBuffer(walk,"_LeisureAreas",areas);shader.SetBuffer(reset,"_DrawArgs",draw);
                shader.SetInt("_NodeCount",roadCount);shader.SetInt("_NodeStride",roadCount);shader.SetInt("_GoalCount",goalCount);shader.SetInt("_WalkerCount",agents);shader.SetFloat("_Delta",1f/30);shader.SetFloat("_Speed",2.8f);shader.SetFloat("_DrawRange",1e8f);shader.SetFloat("_SidewalkOffset",3);shader.SetVector("_CameraBody",new Vector3(0,120010,10));var planes=new Vector4[6];for(int i=0;i<6;i++)planes[i]=new Vector4(0,0,0,1e8f);shader.SetVectorArray("_Frustum",planes);SettlementCargoNavigation.DispatchStorage(shader,clear,roadCount*goalCount);
                for(int i=0;i<100;i++){shader.Dispatch(build,1,1,1);yield return null;}
                int steps=park?300:frames;var timing=new List<double>(steps);var clock=Stopwatch.StartNew();double previous=clock.Elapsed.TotalMilliseconds;double checksum=0;
                for(int frame=0;frame<steps;frame++){for(int i=0;i<agents;i++){var schedule=new SettlementDailySchedule(i,i%41,(long)(frame/18000));checksum+=schedule.start;}shader.SetFloat("_Clock",frame/30f);shader.Dispatch(reset,1,1,1);shader.Dispatch(build,1,1,1);shader.Dispatch(walk,(agents+127)/128,1,1);var fence=AsyncGPUReadback.Request(draw);fence.WaitForCompletion();yield return null;double now=clock.Elapsed.TotalMilliseconds;timing.Add(now-previous);previous=now;}
                var final=new Vector4[agents*5];poses.GetData(final);Check(final[0].sqrMagnitude>1,"Actual GPU walkers publish positions: "+agents);if(park){Check(final[4].z<0&&final[4].w>0,"Park visitor remains outside in a seated resting pose");Check(Math.Abs(final[0].y-120000-final[0].x*.1-final[0].z*.2)<.04,"Park wandering follows the sloped ground plane instead of cutting through it");}Check(checksum>0,"Seeded schedule generation executes for the outdoor pool");timing.Sort();long bytes=0;foreach(var buffer in buffers)bytes+=(long)buffer.count*buffer.stride;GetProcessMemoryInfo(GetCurrentProcess(),out var memory,(uint)Marshal.SizeOf<MemoryCounters>());report.results.Add(new Result{population=4096,outdoorAgents=agents,frames=steps,medianMs=timing[steps/2],p95Ms=timing[(int)Math.Ceiling(steps*.95)-1],ticksPerSecond=steps/clock.Elapsed.TotalSeconds,buffers=bytes,allocated=Profiler.GetTotalAllocatedMemoryLong(),reserved=Profiler.GetTotalReservedMemoryLong(),workingSet=(long)memory.workingSet.ToUInt64(),privateBytes=(long)memory.privateBytes.ToUInt64()});
            }finally{foreach(var buffer in buffers)buffer.Dispose();Destroy(shader);}
        }
    }
}
